import threading
from typing import List

class SafeCounter:
    def __init__(self) -> None:
        self._value = 0
        self._lock = threading.Lock()

    @property
    def value(self) -> int:
        with self._lock:
            return self._value

    def increment(self) -> None:
        with self._lock:
            self._value += 1


def count_with_threads(n_threads: int, increments: int) -> int:
    counter = SafeCounter()
    threads: List[threading.Thread] = []

    for _ in range(n_threads):
        t = threading.Thread(target=_increment_counter, args=(counter, increments))
        threads.append(t)

    for t in threads:
        t.start()

    for t in threads:
        t.join()

    return counter.value


def _increment_counter(counter: SafeCounter, count: int) -> None:
    for _ in range(count):
        counter.increment()
